/* Stub overlay lookup for the fast-engine prefix-validation build.
 * The real overlay (runtime/static_overlay.c, generated by
 * tools/static_overlay_lift.py) defines sub_<VA> bodies that collide with the
 * statically lifted generated code during a whole-image link.  For validating
 * the trampoline on the proven prefix we have no run-time self-modified sites,
 * so return 0: recomp_lookup_manual falls through to the normal lookup and a
 * genuinely unlifted address still stops by name. */
#include "recomp_types.h"

recomp_func_t static_overlay_lookup(uint32_t va) { (void)va; return 0; }
